function buildLCA(n, edges, root = 0) {
  const LOG = Math.ceil(Math.log2(n + 1)) + 1;
  const adj = Array.from({ length: n }, () => []);
  for (const [u, v] of edges) { adj[u].push(v); adj[v].push(u); }

  const depth = new Array(n).fill(0);
  const up = Array.from({ length: n }, () => new Array(LOG).fill(root));

  // DFS to compute depth and up[v][0] (direct parent)
  const stack = [[root, -1]];
  while (stack.length) {
    const [v, par] = stack.pop();
    up[v][0] = par === -1 ? root : par; // root is its own ancestor
    for (const u of adj[v]) {
      if (u === par) continue;
      depth[u] = depth[v] + 1;
      stack.push([u, v]);
    }
  }

  // fill binary lifting table
  for (let j = 1; j < LOG; j++)
    for (let v = 0; v < n; v++)
      up[v][j] = up[up[v][j - 1]][j - 1];

  function lca(u, v) {
    // ensure u is deeper
    if (depth[u] < depth[v]) [u, v] = [v, u];

    // lift u to same depth as v
    let diff = depth[u] - depth[v];
    for (let j = 0; j < LOG; j++)
      if ((diff >> j) & 1) u = up[u][j];

    if (u === v) return u;

    // simultaneously lift both until just below LCA
    for (let j = LOG - 1; j >= 0; j--)
      if (up[u][j] !== up[v][j]) { u = up[u][j]; v = up[v][j]; }

    return up[u][0];
  }

  return { lca, depth };
}
